    carriera: () => S(rect(34, 24, 32, 16, TELHA, 3) + rect(34, 46, 32, 16, ORO, 3) + rect(34, 68, 32, 14, VERDE, 3) + line(50, 40, 50, 46, INK, 3) + line(50, 62, 50, 68, INK, 3)),
