    progetto: () => S(rect(28, 30, 44, 42, WEISS, 4) + rect(34, 56, 8, 12, VERDE, 2) + rect(46, 48, 8, 20, ORO, 2) + rect(58, 40, 8, 28, TELHA, 2) + circle(38, 40, 3, GRAU) + circle(50, 36, 3, GRAU) + circle(62, 32, 3, GRAU)),
    cliente: () => S(circle(40, 32, 10, ORO) + path("M28 70 v-13 q0 -10 12 -10 t12 10 v13 z", "#3E6FA8") + rect(48, 44, 24, 26, HOLZ, 3) + circle(56, 34, 6, ROSA) + path("M52 44 q4 -8 8 0", "none", `stroke="${INK}" stroke-width="2.5" fill="none"`)),
